pub fn (g DeviceGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'devices', q.graph.client.prepare_query('devices', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  device_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g DeviceGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// device_column_type returns the V type of a column of `devices`.
fn device_column_type(column string) string {
	return match column {
		'id' { 'string' }
		'name' { 'string' }
		'owner_id' { 'int' }
		else { '' }
	}
}

// order_by_owner_name orders the rows by the `name` of their `owner`.
pub fn (q DeviceQuery) order_by_owner_name() DeviceQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
	})
}

