// with_named_logins loads `logins` as `configure` says into
// `named_logins[name]`, besides any other load of it.
pub fn (q DeviceQuery) with_named_logins(name string, configure ...fn (LoginQuery) LoginQuery) DeviceQuery {
	mut next := q
	mut named := q.named_logins.clone()
	named[name] = configure
	next.named_logins = named
	return next
}

