// with_owner loads each row's `owner` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q DeviceQuery) with_owner(configure ...fn (UserQuery) UserQuery) DeviceQuery {
	mut next := q
	next.with_owner = true
	next.owner_fns = configure
	return next
}

// with_logins loads each row's `logins` (one_to_many `logins`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q DeviceQuery) with_logins(configure ...fn (LoginQuery) LoginQuery) DeviceQuery {
	mut next := q
	next.with_logins = true
	next.logins_fns = configure
	return next
}

// with_groups loads each row's `groups` (many_to_many `groups`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q DeviceQuery) with_groups(configure ...fn (GroupQuery) GroupQuery) DeviceQuery {
	mut next := q
	next.with_groups = true
	next.groups_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q DeviceQuery) all() ![]DeviceNode {
	rows := load.select_where[models.Device](q.graph.client.conn, q.graph.client.prepare_query('devices', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q DeviceQuery) first() !DeviceNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'devices'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q DeviceQuery) nodes(rows []models.Device) ![]DeviceNode {
	mut nodes := rows.map(DeviceNode{
		graph:  q.graph
		device: it
	})
	if q.with_owner {
		found := q.load_owner(rows, q.owner_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.device.id.str()] or { [] }
			if list.len > 0 {
				node.owner = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'owner'
		}
	}
	if q.with_logins {
		found := q.load_logins(rows, q.logins_fns)!
		for mut node in nodes {
			node.logins = found[node.device.id.str()] or { [] }
			node.loaded << 'logins'
		}
	}
	for name, fns in q.named_logins {
		found := q.load_logins(rows, fns)!
		for mut node in nodes {
			node.named_logins[name] = found[node.device.id.str()] or { [] }
		}
	}
	if q.with_groups {
		found := q.load_groups(rows, q.groups_fns)!
		for mut node in nodes {
			node.groups = found[node.device.id.str()] or { [] }
			node.loaded << 'groups'
		}
	}
	for name, fns in q.named_groups {
		found := q.load_groups(rows, fns)!
		for mut node in nodes {
			node.named_groups[name] = found[node.device.id.str()] or { [] }
		}
	}
	return nodes
}

// load_owner loads the `owner` of `rows`, keyed by each row's key.
fn (q DeviceQuery) load_owner(rows []models.Device, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.owner_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_edge_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.owner_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// owner_or_err returns the `owner`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n DeviceNode) owner_or_err() !&UserNode {
	if 'owner' !in n.loaded {
		return NotLoadedError{
			edge: 'devices.owner'
		}
	}
	if target := n.owner {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_logins loads the `logins` of `rows`, keyed by each row's key.
fn (q DeviceQuery) load_logins(rows []models.Device, fns []fn (LoginQuery) LoginQuery) !map[string][]LoginNode {
	mut sub := q.graph.logins()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Login](q.graph.client.conn, 'device_id',
		rows.map(it.id.str()),
		query: q.graph.client.prepare_edge_query('logins', sub.query)!
	)!)!
	mut by_parent := map[string][]LoginNode{}
	for child in children {
		by_parent[child.login.device_id.str()] << child
	}
	return by_parent
}

// logins_or_err returns the `logins`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n DeviceNode) logins_or_err() ![]LoginNode {
	if 'logins' !in n.loaded {
		return NotLoadedError{
			edge: 'devices.logins'
		}
	}
	return n.logins
}

// load_groups loads the `groups` of `rows`, keyed by each row's key.
fn (q DeviceQuery) load_groups(rows []models.Device, fns []fn (GroupQuery) GroupQuery) !map[string][]GroupNode {
	mut sub := q.graph.groups()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('groups', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'device_groups', 'device_id', 'group_id',
			rows.map(it.id.str()), .string, .int, 'groups', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Group](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]GroupNode{}
		for target in found {
			by_key[target.group.id.str()] = target
		}
		mut cut_linked := map[string][]GroupNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'device_groups', 'device_id',
		'group_id', rows.map(it.id.str()), .string, .int)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]GroupNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Group](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('groups', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.group.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

// groups_or_err returns the `groups`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n DeviceNode) groups_or_err() ![]GroupNode {
	if 'groups' !in n.loaded {
		return NotLoadedError{
			edge: 'devices.groups'
		}
	}
	return n.groups
}

// query_owner starts a query of this row's `owner`, which matches
// nothing when the row has none.
pub fn (n DeviceNode) query_owner() UserQuery {
	key := n.device.owner_id
	return n.graph.users().where(load.eq('id', key))
}

// query_logins starts a query of this row's `logins`.
pub fn (n DeviceNode) query_logins() LoginQuery {
	return n.graph.logins().where(load.eq('device_id', n.device.id))
}

// query_groups starts a query of this row's `groups`. It reads the join
// table `device_groups` first, so it can fail.
pub fn (n DeviceNode) query_groups() !GroupQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'device_groups', 'device_id',
		'group_id', [n.device.id.str()], .string, .int)!
	return n.graph.groups().where(load.in_keys('id', pairs.map(it[1]), .int))
}
